(434,2,'product',691,'update',NULL,'{\"user_id\":\"2\",\"product_name\":\"1.6k ohm Resistor\",\"model\":\"\",\"series\":\"\",\"alternative_name\":\"\",\"brand_id\":\"\",\"primary_category_id\":\"\",\"secondary_category_id\":\"\",\"description\":\"The 1.6kohm Resistor is a medium-value resistor commonly used in voltage dividers, audio circuits, sensor interfacing, signal conditioning, transistor biasing, and power supply regulation.\",\"info\":\"A 1.6 kohm resistor is a fixed resistor with a resistance value of 1,600 ohms, commonly used for current limiting, voltage division, and biasing in electronic circuits. It is widely applied in signal conditioning, analog circuits, and general-purpose DIY electronics projects, offering stable and reliable performance.\",\"note\":\"\",\"mrp\":\"149.00\",\"price\":\"149.00\",\"status\":\"active\"}','2026-02-12 09:49:25'),
(435,2,'product',634,'update',NULL,'{\"user_id\":\"2\",\"product_name\":\"10 ohm Resistor\",\"model\":\"\",\"series\":\"\",\"alternative_name\":\"\",\"brand_id\":\"\",\"primary_category_id\":\"\",\"secondary_category_id\":\"\",\"description\":\"The 10ohm Resistor is a low-value fixed resistor widely used for LED current limiting, motor control, power supply regulation, audio damping, and low-ohm voltage divider circuits.\",\"info\":\"A 10 ohm resistor is a low-value fixed resistor used to limit current and reduce voltage in electronic circuits. It is commonly applied in power circuits, LED protection, and current sensing applications.\",\"note\":\"\",\"mrp\":\"50\",\"price\":\"50\",\"status\":\"active\"}','2026-02-12 09:49:41'),
