(841,1,'sub_sector',16,'create',NULL,'{\"sector_title_id\":\"1\",\"sector_id\":\"19\",\"sub_sector_name\":\"Mobile Phones\",\"description\":\"A mobile phone is a portable electronic communication device used for making calls, sending messages, accessing the internet, and running applications. Modern mobile phones, known as smartphones, combine communication, computing, entertainment, and productivity features in a single compact device.\",\"info\":\"A mobile phone is a portable electronic device used for wireless communication. It allows users to make calls, send messages, browse the internet, and run various applications. Modern mobile phones, known as smartphones, function like small computers and combine communication, multimedia, and productivity features in one device.\",\"note\":\"\",\"system_note\":\"\",\"status\":\"active\",\"image\":\"sub-sectors/1771577416253-688321111.jpg\"}','2026-02-20 08:50:16'),
(842,2,'category_group',1,'update',NULL,'{\"name\":\"kk23\",\"info\":\"\",\"description\":\"\",\"status\":\"active\",\"image\":null}','2026-02-20 08:50:53'),
