(1372,1,'product',593,'update',NULL,'{\"product_name\":\"3k ohm Resistor\",\"description\":\"The 3Kohm Resistor is a standard fixed resistor used in voltage dividers, current limiting, biasing circuits, and signal conditioning.\",\"info\":\"A 3 kohm resistor is a fixed resistor with a resistance value of 3,000 ohms, commonly used for current limiting, voltage division, and biasing in electronic circuits. It is widely used in general-purpose and DIY electronics projects.\",\"status\":\"active\",\"model\":\"\",\"series\":\"\",\"alternative_name\":\"\",\"mrp\":\"45.00\",\"note\":\"\",\"mappings\":[{\"primary_id\":413,\"secondary_id\":0,\"brand_id\":232}],\"base_image\":\"products/1771670368197-15725967.jpg\"}','2026-02-21 10:39:28'),
(1373,1,'product',2558,'update',NULL,'{\"product_name\":\"3MM-Heat Shrink sleeve-black\",\"description\":\"The 3 mm black heat shrink sleeve is a reliable insulation and protection solution for electrical wires, joints, and cable terminations\",\"info\":\"Manufactured from high-quality polyolefin material, it shrinks evenly when heat is applied, forming a tight, durable, and moisture-resistant covering around conductors.\",\"status\":\"active\",\"model\":\"\",\"series\":\"\",\"alternative_name\":\"\",\"mrp\":\"10.00\",\"note\":\"\",\"mappings\":[{\"primary_id\":316,\"secondary_id\":442,\"brand_id\":232}],\"base_image\":\"products/1771670389664-487342517.jpg\"}','2026-02-21 10:39:49'),
