(1401,1,'product',2185,'update',NULL,'{\"product_name\":\"4.7uF 160V Capacitor\",\"description\":\"A 4.7µF 160V capacitor is a high-voltage capacitor used for signal coupling, decoupling, timing, and filtering in electronic circuits operating at elevated voltages\",\"info\":\"This value is commonly available as an aluminum electrolytic (polarized) or a film capacitor (non-polarized), depending on stability and lifetime requirements.\",\"status\":\"active\",\"model\":\"\",\"series\":\"\",\"alternative_name\":\"\",\"mrp\":\"199.00\",\"note\":\"\",\"mappings\":[{\"primary_id\":316,\"secondary_id\":442,\"brand_id\":232}],\"base_image\":\"products/1771672061408-931775939.jpg\"}','2026-02-21 11:07:41'),
(1402,1,'product',2188,'update',NULL,'{\"product_name\":\"4.7uF 250V Capacitor\",\"description\":\"A 4.7µF 250V capacitor is a high-voltage capacitor used for signal coupling, decoupling, timing, and filtering in electronic circuits that operate at high DC voltages.\",\"info\":\"This value is commonly available as an aluminum electrolytic (polarized) or a film capacitor (non-polarized), depending on application requirements.\",\"status\":\"active\",\"model\":\"\",\"series\":\"\",\"alternative_name\":\"\",\"mrp\":\"199.00\",\"note\":\"\",\"mappings\":[{\"primary_id\":316,\"secondary_id\":442,\"brand_id\":232}],\"base_image\":\"products/1771672085875-755167252.jpg\"}','2026-02-21 11:08:05'),
