(2345,1,'product',1014,'update',NULL,'{\"product_name\":\"LM329\",\"description\":\"LM329 is a high-precision voltage reference integrated circuit designed to provide a stable and accurate reference voltage for analog and digital circuits.\",\"info\":\"LM329 is a precision voltage reference IC that provides a stable 6.9 V output with very low temperature drift and high accuracy.\",\"status\":\"active\",\"model\":\"\",\"series\":\"\",\"alternative_name\":\"\",\"mrp\":\"1.00\",\"note\":\"It is commonly used where a reliable reference voltage is required for calibration and precision analog circuits.\",\"mappings\":[{\"primary_id\":275,\"secondary_id\":276,\"brand_id\":232},{\"primary_id\":275,\"secondary_id\":0,\"brand_id\":232}],\"base_image\":\"products/1771917345573-541168667.jpg\"}','2026-02-24 07:15:45'),
(2346,1,'product',1016,'update',NULL,'{\"product_name\":\"LM335\",\"description\":\"LM335 is a precision temperature sensor IC that provides an output voltage linearly proportional to absolute temperature (Kelvin).\",\"info\":\"LM335 is a precision temperature sensor IC that outputs a voltage proportional to absolute temperature (10 mV per Kelvin).\",\"status\":\"active\",\"model\":\"\",\"series\":\"\",\"alternative_name\":\"\",\"mrp\":\"1.00\",\"note\":\"It operates like a temperature-dependent Zener diode and provides accurate temperature measurement over a wide range.\",\"mappings\":[{\"primary_id\":275,\"secondary_id\":276,\"brand_id\":232},{\"primary_id\":275,\"secondary_id\":0,\"brand_id\":232}],\"base_image\":\"products/1771917364606-111018487.jpg\"}','2026-02-24 07:16:04'),
