(2866,1,'product',730,'update',NULL,'{\"product_name\":\"ZMCT103C 5A AC Current Sensor Transformer Module\",\"description\":\"ZMCT103C 5A AC Current Sensor Module is a compact, high-precision current transformer module used to measure AC currents up to 5A. It provides an isolated and safe method to sense AC loads by converting the current into a small, proportional voltage signal.\",\"info\":\"The ZMCT103C 5A AC current sensor transformer module is used for non-invasive AC current measurement. It can sense AC currents up to 5A and provides an isolated analog output proportional to the current, ensuring safe measurement.\",\"status\":\"active\",\"model\":\"\",\"series\":\"\",\"alternative_name\":\"\",\"mrp\":\"799.00\",\"note\":\"\",\"mappings\":[{\"primary_id\":8,\"secondary_id\":18,\"brand_id\":232}],\"base_image\":\"products/1772015761596-485295803.jpg\"}','2026-02-25 10:36:01'),
(2867,1,'product',2565,'update',NULL,'{\"product_name\":\"ZMPT101bAC voltage sensor\",\"description\":\"The ZMPT101B AC Voltage Sensor Module is a precision sensing device used to measure alternating current (AC) voltage in single-phase systems.\",\"info\":\"It’s ideal for electronics projects, energy monitoring, automation, and microcontroller applications where accurate AC voltage sensing is needed.\",\"status\":\"active\",\"model\":\"\",\"series\":\"\",\"alternative_name\":\"\",\"mrp\":\"10.00\",\"note\":\"\",\"mappings\":[{\"primary_id\":316,\"secondary_id\":442,\"brand_id\":232}],\"base_image\":\"products/1772015786759-194387586.jpg\"}','2026-02-25 10:36:26'),
