(2932,1,'product',2036,'update',NULL,'{\"product_name\":\"YY Universal Remote\",\"description\":\"“YY” appears in several universal remote model names (e.g., V4 YY Universal Remote Control) which suggests it’s a model or branding suffix rather than a single fixed specification.\",\"info\":\"\",\"status\":\"active\",\"model\":\"\",\"series\":\"\",\"alternative_name\":\"\",\"mrp\":\"1299.00\",\"note\":\"\",\"mappings\":[{\"primary_id\":230,\"secondary_id\":124,\"brand_id\":232}]}','2026-02-26 04:03:09'),
(2933,1,'product',2088,'update',NULL,'{\"product_name\":\"YY Remote\",\"description\":\"The YY Remote ANDROID is a versatile and user-friendly universal remote designed specifically for Android Smart TVs and Android TV Boxes. It offers seamless compatibility with a wide range of brands and models, ensuring easy replacement for lost or damaged original remotes. Built with high-quality materials, this remote delivers responsive and accurate control with soft-touch buttons for a comfortable experience. It supports essential functions such as power, navigation, volume, menu, apps, and quick access keys, allowing smooth operation of your Android TV interface.\",\"info\":\"sutiable for SAMSUNG,REAL ME,ONDIA, MI\",\"status\":\"active\",\"model\":\"\",\"series\":\"\",\"alternative_name\":\"\",\"mrp\":\"900.00\",\"note\":\"\",\"mappings\":[{\"primary_id\":230,\"secondary_id\":124,\"brand_id\":232}]}','2026-02-26 04:05:42'),
