(3237,1,'product',2561,'update',NULL,'{\"product_name\":\"17mm LDR Sensor\",\"description\":\"The 17 mm LDR is a large-size light dependent resistor designed to detect and respond to changes in ambient light intensity\",\"info\":\"Its resistance decreases in bright light and increases in darkness, making it ideal for day/night sensing and light-controlled automation applications.\",\"status\":\"active\",\"model\":\"\",\"series\":\"\",\"alternative_name\":\"LDR Sensor 17mm\",\"mrp\":\"80\",\"note\":\"\",\"mappings\":[{\"primary_id\":78,\"secondary_id\":\"549\",\"brand_id\":232}]}','2026-02-26 14:56:26'),
(3238,1,'product',446,'update',NULL,'{\"product_name\":\"5mm LDR Sensor\",\"description\":\"5mm LDR (Light Dependent Resistor) Sensor is a compact light-sensitive device that changes its resistance based on the intensity of light falling on it. The 5mm size makes it small, easy to mount, and suitable for compact electronic projects.\",\"info\":\"5 mm LDR Sensor (Light Dependent Resistor) is a compact photosensitive component whose resistance decreases as light intensity increases.\",\"status\":\"active\",\"model\":\"\",\"series\":\"\",\"alternative_name\":\"\",\"mrp\":\"50\",\"note\":\"\",\"mappings\":[{\"primary_id\":78,\"secondary_id\":\"549\",\"brand_id\":232}]}','2026-02-26 14:57:52'),
