(3400,1,'product',806,'update',NULL,'{\"product_name\":\"USB to RS485 Converter Adapter\",\"description\":\"The USB to RS485 Converter Adapter is a compact and reliable communication interface that allows a computer or laptop to communicate with RS485-compatible devices through a USB port. It is widely used for industrial automation, PLC communication, CNC machines, motor drivers, security systems, and long-distance sensor networks.\",\"info\":\"USB to RS485 Converter Adapter\",\"status\":\"active\",\"model\":\"\",\"series\":\"\",\"alternative_name\":\"\",\"mrp\":\"999.00\",\"note\":\"\",\"mappings\":[{\"primary_id\":10,\"secondary_id\":0,\"brand_id\":232}]}','2026-02-28 08:18:51'),
(3401,1,'product',1629,'update',NULL,'{\"product_name\":\"USB to RS232 Converter\",\"description\":\"The USB to RS232 Converter is a reliable USB-to-Serial adapter that allows modern computers without serial ports to communicate with RS232 devices.\",\"info\":\"The adapter uses a high-quality USB-serial chipset (Prolific/CH340/FTDI depending on model) for stable and error-free communication.\",\"status\":\"active\",\"model\":\"\",\"series\":\"\",\"alternative_name\":\"\",\"mrp\":\"1200.00\",\"note\":\"\",\"mappings\":[{\"primary_id\":548,\"secondary_id\":\"88\",\"brand_id\":232}]}','2026-02-28 08:20:15'),
