(3901,1,'product',2679,'create',NULL,'{\"product_name\":\"Uniview NVR - S SERIES\",\"description\":\"The Uniview NVR301-16S3 is a 16-channel IP network video recorder designed to centralize, record, manage, and play back video footage from up to sixteen IP security cameras.\",\"info\":\"It\'s part of Uniview’s Easy Series of NVRs, offering a reliable, scalable solution for home, office, retail, warehouse, or commercial video surveillance setups.\",\"status\":\"active\",\"mappings\":[1194],\"model\":\"NVR301-16S3\",\"mrp\":\"1\",\"note\":\"Dry, Ventilated Setup: Place the NVR in a dry, cool, well-ventilated area away from moisture, direct sunlight, and dust to prevent overheating and hardware issues.\",\"base_image\":\"products/1772523177564-661956798.jpg\"}','2026-03-03 07:32:57'),
(3902,1,'product',253,'update',NULL,'{\"product_name\":\"7inch Raspberry Pi HDMI Touch Display\",\"description\":\"The 7-inch HDMI Touch Display is a compact, high-resolution screen designed for Raspberry Pi and other HDMI-compatible boards. It features a 1024×600 IPS panel with capacitive multi-touch support, offering smooth touch response and vibrant color reproduction. \",\"info\":\"7inch Raspberry Pi HDMI Touch 1024×600 is an HDMI interface touchscreen display with a 7-inch capacitive touch panel and 1024×600 resolution, designed for Raspberry Pi and other HDMI-enabled devices\",\"status\":\"active\",\"model\":\"\",\"series\":\"\",\"alternative_name\":\"Raspberry Pi HDMI Touch Display\",\"mrp\":\"7800.00\",\"note\":\"Perfect for DIY projects, embedded systems, and portable computing setups.\",\"mappings\":[{\"primary_id\":323,\"secondary_id\":\"49\",\"brand_id\":232}]}','2026-03-03 07:33:55'),
