(4684,1,'product',2871,'create',NULL,'{\"product_name\":\"Hikvision 16-Channel NVR \",\"description\":\"The DS-7616NXI-K1 supports IP cameras with resolutions up to 12 MP, allowing high-detail surveillance recording.\",\"info\":\"This NVR features Hikvision AcuSense technology, which uses AI to detect human and vehicle movement, reducing false alarms caused by animals, rain, or moving objects.\",\"status\":\"active\",\"mappings\":[359],\"model\":\"DS-7616NXI-K1\",\"alternative_name\":\"NVR 16-Channel\",\"mrp\":\"1\",\"note\":\"Install the NVR in a cool, well-ventilated area to prevent overheating.\",\"base_image\":\"products/1773028800875-823876645.jpg\"}','2026-03-09 04:00:00'),
(4685,1,'product',2872,'create',NULL,'{\"product_name\":\"Hikvision 32-Channel NVR\",\"description\":\"The recorder supports IP cameras with resolutions up to 12 MP, providing very detailed surveillance recording.\",\"info\":\"This NVR provides up to 256 Mbps incoming bandwidth, allowing stable recording from many cameras simultaneously.\",\"status\":\"active\",\"mappings\":[359],\"model\":\"DS-7632NXI-K2 \",\"alternative_name\":\"NVR 32-Channel\",\"mrp\":\"1\",\"note\":\"The NVR can also be accessed remotely through Hik-Connect mobile or PC software, enabling users to view live cameras and playback recordings from anywhere via the internet.\",\"base_image\":\"products/1773029187615-569912716.jpg\"}','2026-03-09 04:06:27'),
