(4784,1,'product',2932,'create',NULL,'{\"product_name\":\"THINKWILL 4G  Solar CCTV Camera\",\"description\":\"The THINKWILL 4G Solar Camera is designed for surveillance in locations where power supply or internet cables are not available, such as farms, construction sites, or remote areas.\",\"info\":\"The camera usually connects to a mobile application where users can watch live video, receive motion alerts, and control camera movement remotely.\",\"status\":\"active\",\"mappings\":[1436],\"alternative_name\":\"Solar CCTV Camera type \",\"mrp\":\"1\",\"alternative_names\":[],\"base_image\":\"products/1773123559397-325600323.jpg\"}','2026-03-10 06:19:19'),
(4785,1,'product',2933,'create',NULL,'{\"product_name\":\"THINKWILL 4G  Wi-Fi Camera \",\"description\":\"The THINKWILL 4G Wi-Fi camera is designed for home, office, and outdoor surveillance. It can transmit live video over the internet so users can watch footage from anywhere using a mobile application.\",\"info\":\"Some models feature PTZ (Pan-Tilt-Zoom) movement, allowing the camera to rotate and monitor a wider area. Motion detection sensors can trigger alerts on the user’s smartphone whenever movement is detected.\",\"status\":\"active\",\"mappings\":[1438],\"alternative_name\":\"Wi-Fi Camera 4G \",\"mrp\":\"1\",\"note\":\"Install the camera at 2–3 m height for better coverage. \",\"alternative_names\":[],\"base_image\":\"products/1773124505019-421097675.jpg\"}','2026-03-10 06:35:05'),
(4786,1,'brand',297,'create',NULL,'{\"user_id\":\"1\",\"brand_name\":\"MAXELON \",\"description\":\"MAXELON Earbuds are true wireless stereo (TWS) Bluetooth earphones designed for listening to music, making calls, gaming, and watching videos without wires. They connect to smartphones, tablets, laptops, and other Bluetooth devices.\",\"info\":\"Maxelon earbuds are compact in-ear wireless earphones that come with a charging case for convenient storage and charging.\",\"note\":\"\",\"system_note\":\"\",\"icon_text\":\"\",\"link\":\"\",\"status\":\"active\",\"image\":\"brands/1773135377090-80295040.png\"}','2026-03-10 09:36:17'),
