(6309,5,'product',3726,'create',NULL,'{\"product_name\":\"ERD  switching mode power supply\",\"description\":\"An ERD Switching Mode Power Supply (SMPS) is a device that converts AC 230V electricity into stable DC power (mainly 12V) for CCTV cameras, DVRs, LED lights, and other electronic devices.\",\"info\":\"The ERD Switching Mode Power Supply (SMPS) is an electronic device that converts AC (230V) electricity into stable DC output (commonly 12V). It is widely used to power CCTV cameras, DVRs, LED lights, routers, and other electronic devices.\",\"status\":\"active\",\"mappings\":[952],\"alternative_names\":[\" switching mode power supply\"],\"mrp\":\"1199\",\"base_image\":\"products/1775706360718-995675060.jpg\"}','2026-04-09 03:46:00'),
(6310,5,'product',3727,'create',NULL,'{\"product_name\":\"Sony Smart Andriod LED Projector \",\"description\":\"A Smart Android LED Projector is a modern multimedia device that projects videos, images, and presentations onto a large screen or wall while running on the Android operating system.\",\"info\":\"It works like a smart TV + projector combined, allowing you to stream content directly without extra devices.\",\"status\":\"active\",\"mappings\":[2078],\"alternative_names\":[\"Smart Andriod LED Projector \",\" LED Projector \"],\"mrp\":\"4599\",\"base_image\":\"products/1775706723511-320944070.jfif\"}','2026-04-09 03:52:03'),
