(6406,5,'sector',32,'create',NULL,'{\"user_id\":\"5\",\"sector_title_id\":\"34\",\"sector_name\":\"Building Construction\",\"description\":\"Construction is the process of assembling infrastructure, buildings, and industrial facilities, ranging from planning and design to final erection. It involves distinct phases like site preparation, foundation work, and structural development. Major sectors include residential, commercial, and industrial projects, which are crucial for urban development and economic growth.\",\"info\":\"\",\"note\":\"\",\"system_note\":\"\",\"icon_name\":\"\",\"link\":\"\",\"status\":\"active\",\"image\":\"sectors/1775722522850-765421317.jpg\"}','2026-04-09 08:15:22'),
(6407,5,'sub_sector',26,'update',NULL,'{\"sector_title_id\":\"34\",\"sector_id\":\"32\",\"sub_sector_name\":\"Building Materials\",\"description\":\"Building Materials are the essential raw and manufactured materials used in the construction of residential, commercial, industrial, and infrastructure projects\",\"info\":\"These materials determine the strength, durability, safety, appearance, and cost of a building. They are selected based on structural requirements, climate conditions, and design needs.\",\"note\":\"\",\"system_note\":\"\",\"status\":\"active\",\"image\":null}','2026-04-09 08:15:49'),
(6408,5,'sub_sector',27,'update',NULL,'{\"sector_title_id\":\"34\",\"sector_id\":\"32\",\"sub_sector_name\":\"Construction Material\",\"description\":\"Construction Materials are the essential raw, processed, and manufactured materials used in building and infrastructure projects.\",\"info\":\"These materials form the foundation, structure, and finish of residential, commercial, industrial, and infrastructure developments. The quality of construction materials directly affects a structure’s strength, durability, safety, and lifespan.\",\"note\":\"\",\"system_note\":\"\",\"status\":\"active\",\"image\":null}','2026-04-09 08:16:15'),
